raw = []
for req, name, facts, arch in B:
    raw.append({"req": req, "facts": facts, "check": ({"name": name} if name else {}),
                "arch": [(q, f"{b}\n\n{v}", b) for (q, b, v) in arch]})
build("signoff", raw, seed=202)
